type Client struct {
	http    *http.Client
	cfg     config.CerebrasConfig
	limiter *RateLimiter
	log     *slog.Logger

	reqCount    atomic.Int64
	errCount    atomic.Int64
	tokensCount atomic.Int64
}

func NewClient(cfg config.CerebrasConfig, log *slog.Logger) *Client {
	if log == nil {
		log = slog.Default()
	}
	return &Client{
		http: &http.Client{
			Timeout: cfg.Timeout,
			Transport: &http.Transport{
				MaxIdleConns:        64,
				MaxIdleConnsPerHost: 32,
				MaxConnsPerHost:     16,
				IdleConnTimeout:     90 * time.Second,
			},
		},
		cfg:     cfg,
		limiter: NewRateLimiter(cfg.RequestsPerMin, cfg.BurstSize),
		log:     log.With("component", "cerebras"),
	}
}

