func extractJSON(s string) string {
	start, end := -1, -1
	for i := 0; i < len(s); i++ {
		if s[i] == '{' && start == -1 {
			start = i
		}
		if s[i] == '}' {
			end = i
		}
	}
	if start >= 0 && end > start {
		return s[start : end+1]
	}
	return s
}

func (c *Client) Health(ctx context.Context) error {
	probeCtx, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()

	_, err := c.Chat(probeCtx, ChatRequest{
		Messages:  BuildMessages("ping", "responde: ok"),
		MaxTokens: 5,
	})
	return err
}

func (c *Client) Stats() (reqs, errs, tokens int64, remaining float64) {
	return c.reqCount.Load(), c.errCount.Load(), c.tokensCount.Load(), c.limiter.RemainingTokens()
}

func (c *Client) Limiter() *RateLimiter { return c.limiter }
func (c *Client) Config() config.CerebrasConfig { return c.cfg }
